-- 一、创建数据表
CREATE TABLE crafts (
    id VARCHAR(15) PRIMARY KEY,              -- 工艺ID
    process_description TEXT NOT NULL,       -- 工艺流程
    patent_number VARCHAR(20),               -- 专利号
    intensity_grade VARCHAR(5) CHECK (intensity_grade IN ('A','AA','AAA')) -- 强度分级
);

CREATE TABLE handcraft_bracelets (
    id SERIAL PRIMARY KEY,                   -- 主键
    sku VARCHAR(20) NOT NULL UNIQUE,         -- 产品编号
    series VARCHAR(50) NOT NULL,             -- 所属系列
    name VARCHAR(100) NOT NULL,              -- 产品名称
    material VARCHAR(100) NOT NULL,          -- 核心材质
    specification TEXT NOT NULL,             -- 规格参数
    craft_id VARCHAR(15) REFERENCES crafts(id), -- 工艺ID（外键）
    diameter NUMERIC(4,1) NOT NULL,          -- 珠径(mm)
    bead_count INTEGER NOT NULL,             -- 珠子数量
    weight NUMERIC(5,1) NOT NULL,            -- 重量(g)
    origin VARCHAR(100) NOT NULL,            -- 原料产地
    cost_price NUMERIC(8,2) NOT NULL,        -- 成本价(元)
    retail_price NUMERIC(8,2) NOT NULL,      -- 零售价(元)
    version VARCHAR(10) NOT NULL,            -- 工艺版本
    stock INTEGER NOT NULL DEFAULT 0,        -- 库存
    oil_content NUMERIC(4,1),                -- 含油量(%)
    density NUMERIC(4,3),                   -- 密度(g/cm³)
    launch_date DATE NOT NULL,               -- 上市日期
    certification_id VARCHAR(20),            -- 认证编号
    created_at TIMESTAMPTZ DEFAULT NOW(),    -- 创建时间
    updated_at TIMESTAMPTZ DEFAULT NOW()     -- 更新时间
);

